from pathlib import Path
import json
R=Path(__file__).resolve().parent;P=json.loads((R/'plan.json').read_text())
# Selection rules are editorial interpretations; the corresponding clocked footage is the evidence.
recipes={
'convergence':dict(ids=['intro-map','connectors','demo-context-overlay'],relationship='Several sources feed one context or query route.',why='A labeled convergence map makes the source-to-consumer relationship explicit while preserving source identity.',alternative='A list of connector logos',reject='A list names sources but does not explain how they participate in the answer.',motion='Reveal sources first; draw their connector paths next; reveal or activate the destination last. Hold the completed route.',persist='Keep source labels and the destination fixed after the build.',risk='Converging arrows can wrongly imply ingestion, copying, or real-time synchronization. Label the access mode: search, SQL, or tool call.'),
'family-comparison':dict(ids=['product-family'],relationship='Related products share foundations but serve different jobs.',why='Depth establishes a shared family before peer cards separate the roles.',alternative='An execution pipeline',reject='A pipeline would imply that one product executes another.',motion='Preserve the front card; move hidden peers out from behind it; retain readable card planes during the spread.',persist='Front-card scale and independent presenter tile.',risk='Depth must not imply an architectural dependency.'),
'failure-repair':dict(ids=['wrong-source','ambiguity','context-repair'],relationship='The same question produces a wrong answer when its source or definition is missing.',why='A concrete question and visible error isolate the cause before adding the missing context.',alternative='An abstract ontology network',reject='A network cannot identify which missing definition caused this particular error.',motion='Establish the question-to-answer route; expose the wrong choice; add the specific source or rule that repairs that route.',persist='Keep the question and outcome visible across the repair.',risk='Do not imply that every error is solved by adding context; permissions, data quality and model behavior may also matter.'),
'architecture-focus':dict(ids=['architecture','ranking'],relationship='A component belongs to a larger system and must be examined in place.',why='A stable overview gives the viewer a location before attention shifts to a sub-system.',alternative='Replace the overview with an unrelated full-screen detail slide',reject='The viewer loses the connection between the detail and the architecture.',motion='Start at the complete map; dim context selectively; move the inner camera or enlarge only the active region; hold the readable detail.',persist='Fixed outer stage, presenter, component names and relative relationships.',risk='A camera move must not resize the presenter or push the active labels outside the panel.'),
'governed-hierarchy':dict(ids=['modeled'],relationship='Metric definitions, explanatory pages and domains share a governance parent.',why='Containment and parent-child connectors express organization more precisely than decorative data nodes.',alternative='Three floating feature cards',reject='Equal unconnected cards omit the shared governing layer and grouping relationship.',motion='Introduce the first governed object, add its parent, expose peer objects, then show the group and downstream consumers.',persist='Shared parent and the first object remain visible as peers are introduced.',risk='Visual nesting must correspond to an actual product relationship; do not invent inheritance or access semantics.'),
'evidence-accumulation':dict(ids=['learned'],relationship='Repeated work and concrete sources provide contextual signals.',why='Small labeled examples show where context originates before returning to the larger abstraction.',alternative='An unlabeled glowing knowledge graph',reject='A glowing network shows complexity but does not teach which behavior supplies useful context.',motion='Show a small source set; accumulate examples sequentially; keep completed examples still.',persist='The learned-context label and one current example group.',risk='Do not suggest that a signal is certified truth or that every user action automatically creates a governed definition.'),
'benchmark':dict(ids=['benchmark','benchmark-return'],relationship='Multiple methods are compared on accuracy and runtime.',why='Paired bar charts expose the two trade-offs and keep the measured values visible.',alternative='A single improvement percentage',reject='A single number hides runtime and the comparator values.',motion='Build bars from a common baseline; introduce the interpretation after the values; reuse the same chart during the follow-up.',persist='Axes, values, method order and source qualification.',risk='Treat source-reported measurements as historical claims. Do not generalize them to a new product or workload.'),
'feature-evidence':dict(ids=['memory','documents','agent-intro','orchestration','surfaces'],relationship='A named capability is supported by a visible product interaction.',why='A stable heading teaches the capability while authentic UI provides evidence of the interaction.',alternative='A fabricated product screenshot',reject='A fabricated screen could misrepresent available functionality and execution.',motion='Hold heading placement; switch the active supporting point as the corresponding real interaction appears.',persist='Heading, feature-point order and authentic UI viewport.',risk='The screenshot or clip demonstrates only the visible version and permissions; do not infer general availability.'),
'controlled-action':dict(ids=['external-tools','actions','skills'],relationship='Work crosses tool boundaries under explicit governance.',why='A route and named control point show where a write or reusable skill is constrained.',alternative='Tool logos surrounding an agent',reject='Logos show compatibility but omit control and distribution boundaries.',motion='Establish the actor, introduce the gateway, draw the permitted route, then expose sharing or scope choices.',persist='Control point and current actor remain in place.',risk='Arrows must distinguish read, write and share. A diagram is explanatory, not evidence that an operation succeeded.'),
'peer-needs':dict(ids=['governance','starting-summary'],relationship='Several needs or stages have equal conceptual rank.',why='Aligned peer cards give each need equal weight and make comparison easy.',alternative='A nested hierarchy',reject='Nesting would imply that one peer is a subtype or permission parent of another.',motion='Settle the first card, compress it coherently if space is needed, then introduce equal peers on the same baseline.',persist='Shared card height, type hierarchy and reading order.',risk='Use sequence numbers only when order matters. Three items alone is not a reason to use cards.'),
'agent-delegation':dict(ids=['agents'],relationship='A parent agent delegates to specialized agents and connects to resources.',why='A labeled tree differentiates ownership, specialization and resource connections.',alternative='A circle of interchangeable agent icons',reject='An undirected circle hides who delegates work and which nodes are resources.',motion='Start with inputs or the parent; introduce children individually; draw the relevant branch after the child label appears.',persist='Parent position and stable child slots.',risk='Do not confuse an agent hierarchy with data lineage or imply autonomous execution without source evidence.'),
'rollout':dict(ids=['rollout-one','rollout-two'],relationship='A team follows an ordered implementation process.',why='A persistent milestone rail shows both the current task and its place in the rollout.',alternative='Independent full-screen checklist slides',reject='Separate slides lose accumulated progress and the relationship between steps.',motion='Retain completed milestones; add the next marker; update supporting examples below; pan only when the rail needs space.',persist='Milestone order and active-step treatment.',risk='Small faded text must remain legible; a timeline is not a promise about duration.'),
'fixed-emphasis':dict(ids=['best-practices'],relationship='The narration walks through a fixed set of recommendations.',why='Stable positions let the viewer scan the whole set while emphasis identifies the current point.',alternative='Replace the entire screen for each recommendation',reject='Replacement forces the viewer to rebuild the list and obscures its total scope.',motion='Keep all rows stationary; advance text emphasis at the spoken topic change; hold after each change.',persist='Row positions, number order and line breaks.',risk='Do not fade inactive rows below useful contrast or move the active row into a different position.'),
'live-demo':dict(ids=['demo-one-start','demo-one','demo-two'],relationship='The product executes a visible workflow.',why='Authentic interface footage shows the actual steps and results.',alternative='Recreated illustrative UI',reject='An illustration cannot verify actual execution or output.',motion='Retain the recording and source clock, including pauses and result changes; static presenters remain separate.',persist='Original UI evidence and narration.',risk='Reuse is explicitly disclosed; this is not newly recorded product execution.'),
'chapter':dict(ids=['demo-one-title','outcomes-title','demo-two-title','getting-started-title'],relationship='The explanation changes chapter.',why='A short title card resets attention without adding conceptual detail.',alternative='A diagram on every transition',reject='A diagram would add a relationship the narration is not teaching.',motion='Brief chapter hold, then cut to the new teaching surface.',persist='Concise title and consistent chapter treatment.',risk='Do not confuse chapter decoration with an explanatory graphic.'),
'presenter':dict(ids=['opening','host-topic','guest-context','context-in-heads','host-benchmark','host-memory','host-outcomes','host-governance','host-start','closing'],relationship='The speaker frames or reflects on the explanation.',why='A deliberate presenter hold allows the narration to frame the next visual.',alternative='Continuous decorative motion',reject='Motion would compete with framing language rather than explain it.',motion='Static fictional presenter placeholder; short callout only when explicitly named in the source.',persist='Presenter and framing layout.',risk='Static placeholders do not imply lip sync or endorsement by a real speaker.')}
rows=[]
for s in P['scenes']:
 key,nextrecipe=next((k,v) for k,v in recipes.items() if s['id'] in v['ids']);r={k:v for k,v in nextrecipe.items() if k!='ids'};r.update({'scene':s['id'],'template':key,'source_start':s['source_start'],'source_end':s['source_end'],'source_evidence':f'comparison/{s["id"]}.mp4','classification':'Selection reasoning is editorial interpretation; source events are sampled observations; timing is estimated.','adaptation_rule':'Use the relationship and state roles for a new transcript; derive new timings from new narration. Never copy the source benchmark or Databricks behavior into Fabric without verification.'});rows.append(r)
(R/'recipes.json').write_text(json.dumps(rows,indent=2))
md=['# Teaching and motion recipes','', 'These are editorial interpretations grounded in the clocked source study. The native reconstruction is a review artifact, not proof of exact source fidelity. For a new technical script, select by the relationship being taught and verify product claims before creating assets.','']
for r in rows:
 md.extend([f'## {r["scene"]} — {r["template"]}',f'**Relationship:** {r["relationship"]}',f'**Why:** {r["why"]}',f'**Motion:** {r["motion"]}',f'**Keep stable:** {r["persist"]}',f'**Alternative:** {r["alternative"]}. {r["reject"]}',f'**Misuse risk:** {r["risk"]}',''])
(R/'RECIPES.md').write_text('\n\n'.join(md))
skill=R.parent/'.agents/skills/technical-video-explainer';(skill/'references/full-video-recipes.json').write_text(json.dumps(rows,indent=2));p=skill/'SKILL.md';text=p.read_text();text+='\n\n## Whole-video reference extension\n\nThe project `full-video/` extends the reference study across the uploaded 34:28 source with 44 continuous sections. Read `references/full-video-recipes.json` for relationship-based selection, motion roles, alternatives and misuse risks. Inspect the project `full-video/review.html` and `full-comparison.mp4` for source-clock comparisons. `full-video/graphics.py` supplies editable native display-list scenes and `render.py` renders the authorized reconstruction. UI footage and narration reuse source evidence; presenter faces are static fictional placeholders.\n\nThe complete timeline does not certify every micro-transition: section boundaries and many events come from a 1fps scan plus prior dense samples. Vector geometry, curves, icons and some timings remain approximate. Review fidelity explicitly. For a new script, reuse the teaching relationships and components, then research new claims and align to its own narration. This remains an implemented reference adapter, not an arbitrary-script compiler or trained model.\n';p.write_text(text)
print(len(rows),'scene recipes written')
